## Part 3

The code below is the core. The author keeps the main method small by splitting responsibilities.

```typescript
// core implementation
function urlcatImpl(
  pathTemplate: string,
  params: ParamMap,
  baseUrl: string | undefined,
  config: UrlCatConfiguration
) {
    // step 1: path('/users/:id/posts', { id: 1, limit: 30 }) -> "/users/1/posts" and remaining { limit: 30 }
  const { renderedPath, remainingParams } = path(pathTemplate, params);
    // step 2: drop null / undefined properties
  const cleanParams = removeNullOrUndef(remainingParams);
    // step 3: {limit: 30} -> limit=30
  const renderedQuery = query(cleanParams, config);
    // step 4: join into /users/1/posts?limit=30
  const pathAndQuery = join(renderedPath, '?', renderedQuery);

    // step 5: if baseUrl exists, build the full URL
  return baseUrl ? joinFullUrl(renderedPath, baseUrl, pathAndQuery) : pathAndQuery;
}
```

